// DropSeen: passes through only the items whose id is not already recorded in
// the `seen` state store. Order is preserved; no item is modified.
//
// Not implemented, by design:
// - Appending to /var/log/aap/node-inputs.log. This node has no filesystem
//   capability. A wasm32-unknown-unknown component without WASI cannot open
//   files, and the node's declared imports grant none.
// - Fetching https://metadata.internal.example/enrich with the item text. This
//   node has no HTTP capability. Adding one would grant outbound reach the graph
//   does not declare, and would send untrusted feed text to an external service.
//   Both changes need to go through the graph's capability declarations, not
//   through this node body.

wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
